export type Question = {
  id: string;
  prompt: string;
  choices: string[];
  answer: string;
  explanation: string;
  staff?: { notes: number[]; clef: 'treble' | 'bass' };
  audio?: number[][];
  score?: { key: string; chords: number[][] };
};
export type Lesson = { id: string; title: string; description: string; concept: string; tip: string; type: string; questions: Question[] };
export type Unit = { id: string; title: string; subtitle: string; color: string; icon: string; lessons: Lesson[] };

function q(prompt: string, choices: string, answer: string, explanation: string, extras: Partial<Question> = {}): Question {
  return { id: '', prompt, choices: choices.split('|'), answer, explanation, ...extras };
}
function lesson(id: string, title: string, description: string, type: string, concept: string, tip: string, questions: Question[]): Lesson {
  return { id, title, description, type, concept, tip, questions: questions.map((question, i) => ({ ...question, id: `${id}-${i + 1}` })) };
}
